package com.commutemate.matching;
import java.util.LinkedHashMap; import java.util.Map; import org.springframework.stereotype.Component;
@Component public class MatchingEngine { public MatchScore score(MatchCandidate c, MatchingPolicy p) { Map<String,Double> d=new LinkedHashMap<>(); d.put("route",bounded(c.route()));d.put("schedule",bounded(c.schedule()));d.put("preference",bounded(c.preference()));d.put("social",bounded(c.social()));d.put("history",bounded(c.history()));d.put("parking",bounded(c.parking()));d.put("reliability",bounded(c.reliability())); double total=d.get("route")*p.route()+d.get("schedule")*p.schedule()+d.get("preference")*p.preference()+d.get("social")*p.social()+d.get("history")*p.history()+d.get("parking")*p.parking()+d.get("reliability")*p.reliability(); return new MatchScore(round(total),d,explain(d)); } private static String explain(Map<String,Double>d){return d.entrySet().stream().sorted(Map.Entry.<String,Double>comparingByValue().reversed()).limit(2).map(e->e.getKey()+" "+Math.round(e.getValue())+"%").reduce((a,b)->a+" + "+b).orElse("Compatible commute");} private static double bounded(double v){return Math.max(0,Math.min(100,v));} private static double round(double v){return Math.round(v*100.0)/100.0;} }
